import{_ as l,o as a,c as i,a5 as t}from"./chunks/framework.-jms6n7v.js";const g=JSON.parse('{"title":"다른 DB에서 옮기기","description":"지금 쓰는 임베디드 데이터베이스에서 애플리케이션의 데이터를 DaruDB로 옮기는 방법을 데이터베이스마다 한 페이지씩 정리했습니다.","frontmatter":{"title":"다른 DB에서 옮기기","order":1,"prev":{"text":"성능","link":"/ko/performance"},"next":{"text":"SQLite","link":"/ko/migration/sqlite"}},"headers":[{"level":2,"title":"옮기는 순서","slug":"옮기는-순서","link":"#옮기는-순서","children":[]},{"level":2,"title":"복사는 어디서 하나","slug":"복사는-어디서-하나","link":"#복사는-어디서-하나","children":[]},{"level":2,"title":"빠르게 복사하기","slug":"빠르게-복사하기","link":"#빠르게-복사하기","children":[]},{"level":2,"title":"가이드","slug":"가이드","link":"#가이드","children":[]}],"relativePath":"ko/migration/index.md","filePath":"ko/migration/index.md","lastUpdated":1792917766000}'),r={name:"ko/migration/index.md"};function o(d,e,n,s,c,h){return a(),i("div",null,[...e[0]||(e[0]=[t('<h1 id="다른-데이터베이스에서-옮기기" tabindex="-1">다른 데이터베이스에서 옮기기 <a class="header-anchor" href="#다른-데이터베이스에서-옮기기" aria-label="Permalink to &quot;다른 데이터베이스에서 옮기기&quot;">​</a></h1><p>지금 쓰는 임베디드 데이터베이스에서 애플리케이션의 데이터를 DaruDB로 옮기는 방법을 데이터베이스마다 한 페이지씩 정리했습니다.</p><p>DaruDB 파일의 스키마를 바꾸는 방법은 가이드의 <a href="./../guide/migrations">마이그레이션</a>에 있습니다.</p><h2 id="옮기는-순서" tabindex="-1">옮기는 순서 <a class="header-anchor" href="#옮기는-순서" aria-label="Permalink to &quot;옮기는 순서&quot;">​</a></h2><p>모든 가이드가 같은 네 단계를 따르고, 원래 파일은 건드리지 않습니다.</p><ol><li><strong>스키마를 선언합니다.</strong> 원래 데이터베이스가 담던 것을 담을 수 있게 테이블이나 클래스마다 컬렉션을, 열이나 속성마다 필드를 둡니다. 가이드마다 무엇이 무엇에 대응하는지, 아직 대응하는 것이 없는 것은 무엇인지 표로 정리했습니다.</li><li><strong>데이터를 복사합니다.</strong> 원래 파일을 그 라이브러리로 읽기 전용으로 열고, 새 DaruDB 파일에 객체를 쓰는 코드를 돌립니다. 레코드의 키를 객체의 키로 그대로 옮기면 레코드 사이의 참조가 모두 링크로 살아남습니다.</li><li><strong>복사본을 확인합니다.</strong> 테이블이나 클래스마다 레코드 수를 컬렉션의 객체 수와 비교하고, 새 파일에 <a href="./../guide/tools#파일-검사하기">무결성 검사</a>를 돌립니다.</li><li><strong>애플리케이션이 새 파일을 쓰게 바꿉니다.</strong> 원래 파일은 애플리케이션이 새 파일로 한동안 문제없이 돈 뒤에 정리합니다.</li></ol><h2 id="복사는-어디서-하나" tabindex="-1">복사는 어디서 하나 <a class="header-anchor" href="#복사는-어디서-하나" aria-label="Permalink to &quot;복사는 어디서 하나&quot;">​</a></h2><p>서버의 데이터는 한곳에 있으니 스크립트로 한 번 복사하면 됩니다. 앱의 데이터는 기기마다 있으므로, 복사는 앱 안에서 합니다. 옮기는 버전이 처음 실행될 때, 원래 파일을 열기 전에 한 번 합니다. Dart 가이드가 이렇게 합니다. 복사본은 <code>app.darudb.part</code>라는 다른 이름으로 쓰고 닫은 뒤에 제자리로 이름을 바꾸므로, 충돌하거나 앱을 닫아서 끊긴 복사는 다음 실행 때 처음부터 다시 합니다. 원래 파일은 그다음 버전에서야 지웁니다. 다른 언어의 코드도 같은 방법으로 중간에 끊겨도 안전하게 만들 수 있습니다.</p><h2 id="빠르게-복사하기" tabindex="-1">빠르게 복사하기 <a class="header-anchor" href="#빠르게-복사하기" aria-label="Permalink to &quot;빠르게 복사하기&quot;">​</a></h2><ul><li><strong>트랜잭션 하나에 객체 여럿.</strong> 복사 코드는 쓰기 트랜잭션마다 객체를 천 개씩 씁니다. 객체마다 커밋하지 않고 천 개에 커밋 한 번으로 끝납니다.</li><li><strong>지연 커밋으로 쓰고 마지막에 닫기.</strong> 트랜잭션마다 디스크를 기다리지 않고 커밋하고, 마지막에 데이터베이스를 닫을 때 한꺼번에 디스크에 기록합니다. 어떤 이유로든 복사가 중간에 멈추면 그 파일을 지우고 다시 복사하면 되므로, 기다리지 않아도 잃는 것이 없습니다.</li><li><strong>순서는 상관없습니다.</strong> 링크는 아직 없는 객체를 가리켜도 되므로 컬렉션을 어떤 순서로 복사해도 됩니다.</li></ul><h2 id="가이드" tabindex="-1">가이드 <a class="header-anchor" href="#가이드" aria-label="Permalink to &quot;가이드&quot;">​</a></h2><p>사이드바에서 고른 언어의 가이드입니다.</p><div class="lang-only" data-code-lang="rust"><ul><li><a href="./sqlite">SQLite</a>: 테이블과 행, 인덱스. <code>rusqlite</code>로 읽습니다.</li><li><a href="./lmdb">LMDB</a>: 바이트를 담는 이름 있는 데이터베이스. <code>heed</code>로 읽습니다.</li><li><a href="./redb">redb</a>: 타입이 정해진 테이블과 멀티맵 테이블.</li><li><a href="./sled">sled</a>: 바이트를 담는 트리.</li></ul></div><div class="lang-only" data-code-lang="node"><ul><li><a href="./sqlite">SQLite</a>: 테이블과 행, 인덱스. <code>node:sqlite</code>로 읽습니다.</li><li><a href="./realm">Realm</a>: 객체 스키마와 링크, 내장 객체. <code>realm</code>으로 읽습니다.</li><li><a href="./lmdb">LMDB</a>: 이름 있는 데이터베이스. <code>lmdb</code>로 읽습니다.</li><li><a href="./level">LevelDB</a>: JSON 값을 담는 서브레벨. <code>classic-level</code>로 읽습니다.</li></ul></div><div class="lang-only" data-code-lang="dart"><ul><li><a href="./sqlite">SQLite</a>: 테이블과 행, 인덱스. Flutter 앱 안에서 <code>sqflite</code>로 읽습니다.</li><li><a href="./realm">Realm</a>: 객체 스키마와 링크, 내장 객체. Flutter 앱 안에서 <code>realm</code>으로 읽습니다.</li><li><a href="./hive">Hive</a>: 박스와 타입 어댑터. Flutter 앱 안에서 <code>hive_ce</code>로 읽습니다.</li></ul></div><div class="lang-only" data-code-lang="python"><ul><li><a href="./sqlite">SQLite</a>: 테이블과 행, 인덱스. <code>sqlite3</code>로 읽습니다.</li><li><a href="./lmdb">LMDB</a>: 바이트를 담는 이름 있는 데이터베이스. <code>lmdb</code>로 읽습니다.</li><li><a href="./tinydb">TinyDB</a>: JSON 문서를 담는 테이블.</li><li><a href="./shelve">shelve</a>: pickle한 값을 담는 셸프.</li></ul></div>',16)])])}const f=l(r,[["render",o]]);export{g as __pageData,f as default};
